/**
 * Blind Benchmark Gold Expansion: 10 → 50 projects
 *
 * Produces gold/annotations-v2.json (version 6.0):
 *   - 40 style-variant projects (planted-flaw synthetic, generated by generate-projects.ts):
 *     gold findings derived from the generator's plant configuration (TYPES/STYLES)
 *     plus Claude template-review findings (ownership, input validation, TLS, rate limiting).
 *   - 10 original model-variant projects: gold findings carried over unchanged from
 *     annotations.json v5.0 (human-annotated 2026-07-06); only detection fields refreshed
 *     against the current detector scan (reports/batch-scan-results.json).
 *
 * Matching rules (defined BEFORE looking at detections, to avoid benchmark bias):
 *   - Each gold finding is matched at its own function in the scan's perFunction data
 *     (file basename + function name). A finding is detected when that function carries
 *     a violation whose category is in the finding's matcher set.
 *   - handleRequest (server aggregator) also carries project-wide duplicate signals;
 *     gold findings whose function shows nothing are matched against handleRequest.
 *   - False positives are detections that are FACTUALLY WRONG per code review:
 *     session_fixation on a logout function that actually invalidates (splices) sessions.
 *     Detections that are factually true but not in the gold list are "unlabeled" and
 *     excluded from precision (mirrors v5 annotation_issues handling).
 *
 * Usage: npx ts-node blind-benchmark/expand-gold-v6.ts
 */

import * as fs from "fs";
import * as path from "path";
import { execSync } from "child_process";
import { TYPES, STYLES } from "./generate-projects";

const REPORT_PATH = path.resolve(__dirname, "reports", "batch-scan-results.json");
const V1_PATH = path.resolve(__dirname, "gold", "annotations.json");
const V2_PATH = path.resolve(__dirname, "gold", "annotations-v2.json");
const GEN_DIR = path.resolve(__dirname, "generated");

// ═══════════════════════════════════════════════════════════
// Types
// ═══════════════════════════════════════════════════════════

interface GoldFinding {
  id: string;
  file: string;
  function: string;
  category: string;
  severity: string;
  protocol: string;
  description: string;
  fix_suggestion?: string;
  progmune_detected: boolean;
  progmune_verdict: string;
  false_positive: boolean;
  note?: string;
  annotation_issue?: boolean;
  annotation_note?: string;
}

interface ProjectAnnotation {
  project_id: string;
  model: string;
  project_type: string;
  files: string[];
  total_findings: number;
  findings: GoldFinding[];
  progmune_summary: any;
}

interface ScanFunc {
  name: string;
  file: string;
  calls: string[];
  protocolViolations: Array<{ category: string; [k: string]: any }>;
  safeguardViolations: Array<{ category: string; [k: string]: any }>;
}

interface ScanProject {
  project: string;
  perFunction: ScanFunc[];
  [k: string]: any;
}

// ═══════════════════════════════════════════════════════════
// Style-variant gold derivation (plant config + template review)
// ═══════════════════════════════════════════════════════════

function listName(e: string, styleId: string): string {
  return styleId === "C" ? `getAll${e}s` : `list${e}s`;
}

function generateStyleProjectGold(projId: string): ProjectAnnotation {
  const [typeId, styleId] = projId.split("_");
  const t = TYPES.find(x => x.id === typeId)!;
  const s = STYLES.find(x => x.id === styleId)!;
  const entities = t.entities.slice(0, 2);

  const findings: GoldFinding[] = [];
  let n = 0;
  const add = (f: Omit<GoldFinding, "id" | "progmune_detected" | "progmune_verdict" | "false_positive">) => {
    n++;
    findings.push({
      ...f,
      id: `${projId.toUpperCase()}-${String(n).padStart(3, "0")}`,
      progmune_detected: false,
      progmune_verdict: "NOT_CHECKED",
      false_positive: false,
    });
  };

  // 1. Password hashing (planted per style)
  const hashingDesc: Record<string, string> = {
    A: "Password stored as plaintext. No hashing.",
    B: "Password hashed with SHA256 — a fast hash unsuitable for password storage.",
    C: "Password stored as plaintext. No hashing.",
    D: "Password hashed with MD5 — cryptographically broken.",
  };
  add({
    file: "auth.ts", function: s.registerName, category: "protocol_violation", severity: "medium",
    protocol: "Auth", description: hashingDesc[styleId],
    fix_suggestion: "Hash passwords with bcrypt/argon2",
  });

  // 2. Token generation (planted per style)
  const tokenDesc: Record<string, string> = {
    A: 'Token generated as "tok_" + Math.random() — not cryptographically secure, predictable source.',
    B: 'Token generated as "s_" + Date.now() — predictable and forgeable.',
    C: 'Token generated as "sess_" + increment — trivially predictable and forgeable.',
    D: 'Token generated as "jwt_" + Math.random() — not an actual JWT, predictable and forgeable.',
  };
  add({
    file: "auth.ts", function: s.loginName, category: "protocol_violation", severity: "medium",
    protocol: "Auth", description: tokenDesc[styleId],
    fix_suggestion: "Use crypto.randomUUID() or a real signed JWT",
  });

  // 3. Planted no-auth functions (noAuthFns ∩ generated entities)
  const plantedNoAuth = s.noAuthFns.filter(fn =>
    entities.some(e => listName(e, styleId) === fn || `get${e}` === fn));
  for (const fn of plantedNoAuth) {
    const e = entities.find(x => listName(x, styleId) === fn || `get${x}` === fn)!;
    add({
      file: `${e.toLowerCase()}.ts`, function: fn, category: "auth_bypass", severity: "high",
      protocol: "Auth",
      description: `${fn}() has NO authentication check — returns data to unauthenticated callers. Planted by generator (noAuthFns).`,
      fix_suggestion: "Add token verification",
    });
  }

  // 4/5. Template-review findings per entity: ownership on delete, validation on create
  for (const e of entities) {
    const delName = styleId === "C" ? `remove${e}` : `delete${e}`;
    add({
      file: `${e.toLowerCase()}.ts`, function: delName, category: "auth_bypass", severity: "medium",
      protocol: "Auth",
      description: `${delName} verifies the caller's token but not that the item belongs to the caller (ownerId). Any authenticated user can delete others' data.`,
      fix_suggestion: "Check item.ownerId === user.id before delete",
    });
    add({
      file: `${e.toLowerCase()}.ts`, function: `create${e}`, category: "protocol_violation", severity: "low",
      protocol: "Resource",
      description: `No input validation on title/body in create${e}.`,
      fix_suggestion: "Add content validation (length/format)",
    });
  }

  // 6/7. Server-level (aligned with v5 annotation practice)
  add({
    file: "server.ts", function: "handleRequest", category: "resource_leak", severity: "low",
    protocol: "TLS",
    description: "No TLS configuration — API entry point serves plain HTTP routing without HTTPS enforcement.",
    fix_suggestion: "Serve over HTTPS with TLS certificates",
  });
  add({
    file: "server.ts", function: "handleRequest", category: "resource_leak", severity: "low",
    protocol: "Resource",
    description: "No rate limiting on any endpoint — brute force and abuse possible.",
    fix_suggestion: "Add rate limiting middleware",
  });

  return {
    project_id: projId,
    model: "generator",
    project_type: t.name,
    files: ["auth.ts", ...entities.map(e => `${e.toLowerCase()}.ts`), "server.ts"],
    total_findings: findings.length,
    findings,
    progmune_summary: {},
  };
}

// ═══════════════════════════════════════════════════════════
// Detection matching
// ═══════════════════════════════════════════════════════════

// Rule-level matchers per gold finding kind, derived from description keywords
// (fixed before inspecting detection results). Rule names are matched — not just
// categories — because some categories cover multiple distinct rules (e.g.
// data_integrity has both "Foreign Key" and "Audit Trail").
function rulePredicates(f: Pick<GoldFinding, "category" | "description">): Array<(rule: string) => boolean> {
  const d = f.description;
  if (/plaintext|SHA256|MD5|hashing/i.test(d)) return [r => r.startsWith("Password Hashing")];
  if (/Token generated|Token = /i.test(d)) return [r => r.startsWith("Token Security")];
  if (/order.*exists|exists.*order/i.test(d)) return [r => r.includes("Order Verification")];
  if (/order status|refund.*status/i.test(d)) return [r => r.includes("Status Verification")];
  if (/member/i.test(d)) return [r => r === "Room Membership Check" || r === "Authorization (Unauthenticated Access)"];
  if (/belongs to|owner|ownership|ownerId/i.test(d))
    return [r => r === "Authorization (Ownership Check)" || r === "Authorization (Resource Ownership)"];
  if (f.category === "auth_bypass" || /no authentication|authentication check/i.test(d))
    // A no-auth mutation flagged with Ownership Check is still an authorization
    // violation on the exact function — credit it.
    return [r => r === "Authorization (Unauthenticated Access)" || r === "Authorization (Ownership Check)"];
  if (/TLS/i.test(d)) return [r => r === "TLS Enforcement"];
  if (/rate limit/i.test(d)) return [r => r === "Rate Limiting" || r === "API Without Rate Limiting"];
  if (/validation/i.test(d)) return [r => r === "Input Validation"];
  if (f.category === "data_integrity" || /exists/i.test(d)) return [r => r === "Data Integrity (Foreign Key)"];
  if (f.category === "missing_prerequisite") return [r => r.startsWith("Authorization")];
  return [r => r.startsWith("Authorization")];
}

/** safeguard violation rules on a function, or the 'auth' protocol-violation category. */
function rulesOf(fn: ScanFunc): string[] {
  return fn.safeguardViolations.map(v => v.rule as string);
}

function findFunc(proj: ScanProject, f: GoldFinding): ScanFunc | undefined {
  return proj.perFunction.find(x =>
    x.name === f.function && path.basename(x.file) === f.file);
}

function rulesMatch(f: GoldFinding, fn: ScanFunc): boolean {
  const preds = rulePredicates(f);
  if (rulesOf(fn).some(rule => preds.some(p => p(rule)))) return true;
  // Orchestrator-level auth gap findings (e.g. BLOG-001) map to the project-level
  // Auth Protocol violation reported on handleRequest.
  if (f.category === "missing_prerequisite" && fn.name === "handleRequest") {
    if (fn.protocolViolations.some(v => v.category === "auth")) return true;
  }
  return false;
}

/** Match a gold finding against the scan.
 *  Strict localization: only the finding's own function counts. Fallback to the
 *  handleRequest aggregator is allowed ONLY when the function is absent from the
 *  scan (the detector could not localize at all) — generic router-level signals do
 *  not credit findings on functions the detector did examine. */
function matchFinding(proj: ScanProject, f: GoldFinding): boolean {
  const own = findFunc(proj, f);
  if (own) return rulesMatch(f, own);
  const hr = proj.perFunction.find(x => x.name === "handleRequest");
  if (hr) return rulesMatch(f, hr);
  return false;
}

function verdictOf(f: GoldFinding): string {
  if (!f.progmune_detected) return "NOT_CHECKED";
  return f.severity === "critical" ? "BLOCK" : "WARN";
}

/** Factual FP classification: session_fixation detections are factually wrong when the
 *  project's logout function actually invalidates the session (e.g. splices it out of
 *  the store). Every session_fixation detection in such a project counts as a wrong
 *  finding — including the duplicate reported on the handleRequest aggregator. */
function factualFPs(proj: ScanProject, projectId: string): number {
  const projDir = path.join(GEN_DIR, projectId, "src");
  const flagged = proj.perFunction.filter(f =>
    f.safeguardViolations.some(v => v.category === "session_fixation"));
  if (flagged.length === 0) return 0;

  const logoutFns = proj.perFunction.filter(f => /logout|signout|invalidate/i.test(f.name));
  const invalidates = logoutFns.some(f => {
    const filePath = path.join(projDir, path.basename(f.file));
    let src = "";
    try { src = fs.readFileSync(filePath, "utf-8"); } catch { return false; }
    const bodyMatch = src.match(new RegExp(`function\\s+${f.name}[\\s\\S]*?\\n\\}`));
    const body = bodyMatch ? bodyMatch[0] : "";
    return /splice|\.clear\(\)|\.destroy\(|invalidate/i.test(body);
  });

  return invalidates ? flagged.length : 0;
}

function buildSummary(findings: GoldFinding[], fpCount: number): any {
  const detected = findings.filter(f => f.progmune_detected).length;
  const missed = findings.filter(f => !f.progmune_detected);
  const bySeverity: any = {};
  for (const f of findings) {
    bySeverity[f.severity] = bySeverity[f.severity] || { total: 0, detected: 0 };
    bySeverity[f.severity].total++;
    if (f.progmune_detected) bySeverity[f.severity].detected++;
  }
  return {
    total_findings: findings.length,
    detected,
    missed: missed.length,
    detection_rate: findings.length ? Math.round((detected / findings.length) * 1000) / 10 : 0,
    false_positives: fpCount,
    by_severity: bySeverity,
    missed_findings: missed.map(f => `${f.id}: ${f.description.slice(0, 60)}`),
  };
}

// ═══════════════════════════════════════════════════════════
// Main
// ═══════════════════════════════════════════════════════════

function main() {
  const scan: { generated: string; projects: ScanProject[] } =
    JSON.parse(fs.readFileSync(REPORT_PATH, "utf-8"));
  const v1 = JSON.parse(fs.readFileSync(V1_PATH, "utf-8"));

  let detectorCommit = "";
  try {
    detectorCommit = execSync("git rev-parse HEAD", { cwd: path.resolve(__dirname, "..") })
      .toString().trim();
  } catch { /* no git */ }

  const out: any = {
    $description: "Progmune blind-benchmark gold annotations v2 — 50 projects. " +
      "40 style-variant projects: gold from generator plant configuration + template review. " +
      "10 model-variant projects: human-annotated gold from annotations.json v5.0, detection refreshed.",
    annotated_by: "plant-config + template review (style variants); human (model variants, 2026-07-06)",
    annotated_at: "2026-08-15",
    version: "6.0",
    detector_scan_generated: scan.generated,
    detector_commit: detectorCommit,
    projects: [] as ProjectAnnotation[],
    aggregate: {},
  };

  let fpsTotal = 0;

  // ── 40 style-variant projects ──
  const styleProjects: ProjectAnnotation[] = [];
  for (const t of TYPES) {
    for (const s of STYLES) {
      const projId = `${t.id}_${s.id}`;
      const scanProj = scan.projects.find(p => p.project === projId);
      if (!scanProj) {
        console.warn(`⚠️  ${projId}: not in batch scan, skipping`);
        continue;
      }
      const ann = generateStyleProjectGold(projId);
      for (const f of ann.findings) {
        f.progmune_detected = matchFinding(scanProj, f);
        f.progmune_verdict = verdictOf(f);
      }
      const fps = factualFPs(scanProj, projId);
      fpsTotal += fps;
      ann.progmune_summary = buildSummary(ann.findings, fps);
      styleProjects.push(ann);
    }
  }

  // ── 10 model-variant projects: gold unchanged, detection refreshed ──
  const modelProjects: ProjectAnnotation[] = [];
  for (const old of v1.projects as any[]) {
    const scanProj = scan.projects.find(p => p.project === old.project_id);
    if (!scanProj) {
      console.warn(`⚠️  ${old.project_id}: not in batch scan, skipping`);
      continue;
    }
    const ann: ProjectAnnotation = JSON.parse(JSON.stringify(old));
    for (const f of ann.findings) {
      if (f.annotation_issue || f.note?.startsWith("Out of scope")) {
        f.progmune_detected = false;
        f.progmune_verdict = "NOT_CHECKED";
        continue;
      }
      f.progmune_detected = matchFinding(scanProj, f);
      f.progmune_verdict = verdictOf(f);
    }
    const fps = factualFPs(scanProj, old.project_id);
    fpsTotal += fps;
    ann.progmune_summary = buildSummary(ann.findings, fps);
    modelProjects.push(ann);
  }

  const projects: ProjectAnnotation[] = [...styleProjects, ...modelProjects].sort((a, b) =>
    a.project_id.localeCompare(b.project_id));
  out.projects = projects;

  // ── Aggregate ──
  const all: GoldFinding[] = projects.flatMap(p => p.findings);
  const detected = all.filter(f => f.progmune_detected).length;
  const missed = all.length - detected;
  const annotationIssues = all.filter(f => f.annotation_issue).length;
  const outOfScope = all.filter(f => f.note?.startsWith("Out of scope")).length;
  const effectiveTotal = all.length - annotationIssues - outOfScope;
  const effectiveDetected = all.filter(f => f.progmune_detected && !f.annotation_issue && !f.note?.startsWith("Out of scope")).length;
  const precision = detected + fpsTotal > 0 ? Math.round((detected / (detected + fpsTotal)) * 1000) / 10 : 0;

  out.aggregate = {
    projects_annotated: out.projects.length,
    target_projects: 100,
    total_findings: all.length,
    progmune_detected: detected,
    progmune_missed: missed,
    annotation_issues: annotationIssues,
    out_of_scope: outOfScope,
    genuine_fns: missed - annotationIssues - outOfScope,
    overall_recall: Math.round((detected / all.length) * 1000) / 10,
    overall_precision: precision,
    false_positive_rate: Math.round((fpsTotal / (detected + fpsTotal)) * 1000) / 10,
    false_positives_total: fpsTotal,
    effective_recall_excluding_annotation: Math.round((effectiveDetected / effectiveTotal) * 1000) / 10,
    note: "FP = detections factually wrong per code review (session_fixation on logout functions that do invalidate). " +
      "Factually-true detections not in the gold list are 'unlabeled' and excluded from precision — " +
      "mirrors v5 annotation_issues handling. Matching is strict-localization: a finding counts as detected " +
      "only when ITS function carries the corresponding rule; the handleRequest aggregator fallback applies " +
      "only to functions absent from the scan. Ownership findings on delete functions are detected for " +
      "styles B/C (validateSession/verifyToken auth naming) but not A/D (getUser/getCurrentUser) — a real " +
      "localization gap of the current detector.",
  };

  fs.writeFileSync(V2_PATH, JSON.stringify(out, null, 2));
  console.log(`✅ ${V2_PATH}`);
  console.log(`   ${out.projects.length} projects (${styleProjects.length} style + ${modelProjects.length} model)`);
  console.log(`   ${all.length} gold findings | detected ${detected} | missed ${missed}`);
  console.log(`   recall ${out.aggregate.overall_recall}% (effective ${out.aggregate.effective_recall_excluding_annotation}%)`);
  console.log(`   precision ${precision}% | FPs ${fpsTotal}`);
}

main();
